using System.Numerics;
using Content.Shared._ST.Interaction;
using Content.Shared.Stealth.Components;
using Robust.Client.Animations;
using Robust.Client.GameObjects;
using Robust.Shared.Containers;
using Robust.Shared.Map;
using Robust.Shared.Network;
using Robust.Shared.Prototypes;
using Robust.Shared.Random;
using Robust.Shared.Timing;
namespace Content.Client._ST.Interaction;
public sealed class StellarInteractionParticleSystem:EntitySystem
{
 [Dependency] private IRobustRandom _random=default!; [Dependency] private SpriteSystem _sprite=default!; [Dependency] private AppearanceSystem _appearance=default!; [Dependency] private AnimationPlayerSystem _animation=default!; [Dependency] private TransformSystem _xform=default!; [Dependency] private SharedContainerSystem _container=default!; [Dependency] private IGameTiming _timing=default!; [Dependency] private IClientNetManager _net=default!;
 private readonly List<Pending> _pending=new(); private readonly HashSet<(EntityUid,EntityUid)> _shown=new(); private GameTick _shownTick; private const string Key="interaction-particle"; private static readonly TimeSpan Grace=TimeSpan.FromMilliseconds(400); private static readonly TimeSpan Lifetime=TimeSpan.FromSeconds(1);
 private static readonly Dictionary<StellarInteractionParticleType,EntProtoId> Protos=new(){{StellarInteractionParticleType.Use,"StellarInteractionParticleUse"},{StellarInteractionParticleType.Pull,"StellarInteractionParticlePull"},{StellarInteractionParticleType.InHand,"StellarInteractionParticleUse"}};
 public override void Initialize(){base.Initialize();SubscribeAllEvent<StellarInteractionParticleEvent>(OnParticle);}
 public override void FrameUpdate(float frameTime){base.FrameUpdate(frameTime);for(var i=_pending.Count-1;i>=0;i--){var p=_pending[i];if(p.Entity is{} uid&&_timing.RealTime>p.Deadline){QueueDel(uid);p.Entity=null;}if(_timing.RealTime>p.Expiry)_pending.RemoveAt(i);}}
 private void OnParticle(StellarInteractionParticleEvent ev){var a=GetEntity(ev.Performer);var b=GetEntity(ev.Target);if(_timing.CurTick!=_shownTick){_shownTick=_timing.CurTick;_shown.Clear();}if(!_shown.Add((a,b)))return;if(!ev.IsClientEvent){for(var i=0;i<_pending.Count;i++)if(_pending[i].A==a&&_pending[i].B==b){_pending.RemoveAt(i);return;}}var particle=SpawnParticle(ev,a,b);if(ev.IsClientEvent){var deadline=_timing.RealTime+TimeSpan.FromMilliseconds((_net.ServerChannel?.Ping??0)*2)+Grace;_pending.Add(new Pending(a,b,particle,deadline,deadline+Lifetime));}}
 private EntityUid? SpawnParticle(StellarInteractionParticleEvent ev,EntityUid a,EntityUid b){var used=GetEntity(ev.Used);if(!Exists(a)||!Exists(b))return null;if(TryComp<StealthComponent>(a,out var stealth)&&stealth.Enabled)return null;var type=ev.Type;if(type==StellarInteractionParticleType.Pull)(a,b)=(b,a);var ax=Transform(a);var bx=Transform(b);if(ax.MapID==MapId.Nullspace||bx.MapID==MapId.Nullspace||_container.IsEntityOrParentInContainer(a,xform:ax))return null;if(_container.IsEntityOrParentInContainer(b,xform:bx)){if(type==StellarInteractionParticleType.Pull)return null;type=StellarInteractionParticleType.InHand;}if((ax.GridUid??ax.MapUid)is not{} frame)return null;var start=_xform.ToCoordinates(frame,_xform.GetMapCoordinates(a,ax)).Position;var end=_xform.ToCoordinates(frame,_xform.GetMapCoordinates(b,bx)).Position;var uid=Spawn(Protos[type],new EntityCoordinates(frame,start));if(type==StellarInteractionParticleType.InHand){used=b;_xform.SetParent(uid,a);}if(used is{} item&&Exists(item)&&TryComp<SpriteComponent>(item,out var usedSprite)){_appearance.OnChangeData(item,usedSprite);_sprite.CopySprite((item,usedSprite),uid);_sprite.SetDrawDepth(uid,(int)Shared.DrawDepth.DrawDepth.Effects);}var sprite=Comp<SpriteComponent>(uid);sprite.NoRotation=true;var duration=type==StellarInteractionParticleType.Pull?TimeSpan.FromMilliseconds(667):TimeSpan.FromMilliseconds(850);var color=sprite.Color;var track=new AnimationTrackComponentProperty{ComponentType=typeof(TransformComponent),Property=nameof(TransformComponent.LocalPosition),KeyFrames={new AnimationTrackProperty.KeyFrame(start,0f),new AnimationTrackProperty.KeyFrame(end,(float)duration.TotalSeconds,Easings.OutBack)}};var fade=new AnimationTrackComponentProperty{ComponentType=typeof(SpriteComponent),Property=nameof(SpriteComponent.Color),KeyFrames={new AnimationTrackProperty.KeyFrame(color,0f),new AnimationTrackProperty.KeyFrame(color.WithAlpha(0f),(float)duration.TotalSeconds,Easings.InOutCirc)}};var rotation=new AnimationTrackComponentProperty{ComponentType=typeof(SpriteComponent),Property=nameof(SpriteComponent.Rotation),KeyFrames={new AnimationTrackProperty.KeyFrame(_random.NextAngle(Angle.FromDegrees(-40),Angle.FromDegrees(40)),0f),new AnimationTrackProperty.KeyFrame(Angle.Zero,(float)duration.TotalSeconds,Easings.OutBack)}};_animation.Play(uid,new Animation{Length=duration,AnimationTracks={track,fade,rotation}},Key);return uid;}
 private sealed class Pending(EntityUid a,EntityUid b,EntityUid? entity,TimeSpan deadline,TimeSpan expiry){public EntityUid A=a;public EntityUid B=b;public EntityUid? Entity=entity;public TimeSpan Deadline=deadline;public TimeSpan Expiry=expiry;}
}
